fn main() {
    let first = String::from("hello");

    let second = first; // ownership moves from first to second

    // println!("{}", first); // ERROR: first no longer owns the String

    println!("{}", second);
} // second goes out of scope; String is dropped here

fn print_text(text: &String) {
    println!("{}", text);
}

fn main() {
    let message = String::from("hello");

    print_text(&message);

    println!("{}", message); // still valid
}

fn add_world(text: &mut String) {
    text.push_str(" world");
}

fn main() {
    let mut message = String::from("hello");

    add_world(&mut message);

    println!("{}", message);
}
